-- Table: patients
DROP TABLE IF EXISTS "patients" CASCADE;
CREATE TABLE IF NOT EXISTS "patients" (
    "age" INTEGER,
    "cnic" TEXT,
    "created_at" TIMESTAMPTZ,
    "gender" TEXT,
    "id" INTEGER,
    "mobile" TEXT,
    "mr_no" INTEGER,
    "patient_name" TEXT,
    "patient_token" INTEGER,
    "pwd" TEXT,
    "relation" TEXT,
    "relation_name" TEXT,
    "salutation" TEXT,
    "shift" TEXT,
    "user" TEXT,
    "user_id" INTEGER,
    PRIMARY KEY ("mr_no")
);

